## Result
In testing, the prototype placed and retrieved traffic cones effectively while cutting out manual handling. The bigger takeaway: replacing a risky manual job with a simple, well-timed mechanism can make road work faster and, most importantly, keep workers out of live traffic.

## Arduino code
```cpp
#include <Stepper.h>

const int stepsPerRevolution = 2048;
Stepper myStepper(stepsPerRevolution, 8, 10, 9, 11);

// Motor 1 (TT) — channel A
const int ENA = 6, IN1 = 7, IN2 = 5;
// Motor 2 (conveyor TT) — channel B
const int ENB = 3, IN3 = 4, IN4 = 2;

// timing trackers (millis-based, non-blocking)
unsigned long m1Timer = 0;
unsigned long stepTimer = 0;

// motor 1 move/stop cycle state
bool m1Moving = true;
unsigned long m1MoveDur = 500;    // move 0.5 s
unsigned long m1StopDur = 2000;   // stop 2 s

// stepper state
int stepDir = 1;
long stepCount = 0;

void m1Move(int dir, int speed) {
  digitalWrite(IN1, dir ? HIGH : LOW);
  digitalWrite(IN2, dir ? LOW : HIGH);
  analogWrite(ENA, speed);
}
void m1Brake() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, LOW); analogWrite(ENA, 0);
}
void m2Move(int dir, int speed) {
  digitalWrite(IN3, dir ? HIGH : LOW);
  digitalWrite(IN4, dir ? LOW : HIGH);
  analogWrite(ENB, speed);
}

void setup() {
  myStepper.setSpeed(10);
  pinMode(ENA, OUTPUT); pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  pinMode(ENB, OUTPUT); pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  Serial.begin(9600);
  m1Timer = millis();
  stepTimer = millis();
}

void loop() {
  unsigned long now = millis();

  // Motor 2 (conveyor): runs continuously
  m2Move(1, 150);

  // Motor 1: move/stop cycle without freezing anything
  if (m1Moving && now - m1Timer >= m1MoveDur) {
    m1Brake();
    m1Moving = false;
    m1Timer = now;
  } else if (!m1Moving && now - m1Timer >= m1StopDur) {
    m1Move(1, 120);
    m1Moving = true;
    m1Timer = now;
  }

  // Stepper: one step at a time, on its own schedule (~3 ms per step)
  if (now - stepTimer >= 3) {
    myStepper.step(stepDir);
    stepTimer = now;
    stepCount++;
    if (stepCount >= stepsPerRevolution) {  // full turn -> reverse
      stepDir = -stepDir;
      stepCount = 0;
    }
  }
}
```

